def findDuplicate(nums: list[int]) -> int:
    lo, hi = 1, len(nums) - 1
    ans = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        count = sum(1 for x in nums if x <= mid)
        if count > mid:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

